-- Pharmflow core schema for Supabase/Postgres.
create extension if not exists "uuid-ossp";
create type app_role as enum ('OWNER','BRANCH_MANAGER','INVENTORY_MANAGER','PHARMACIST','BILLING_STAFF','ACCOUNTANT');
create type stock_movement_type as enum ('PURCHASE','SALE','PURCHASE_RETURN','SALE_RETURN','ADJUSTMENT','TRANSFER_OUT','TRANSFER_IN','DAMAGE');
create table branches (id uuid primary key default uuid_generate_v4(), name text not null, code text unique not null, address text, gstin text, contact_number text, status text default 'ACTIVE', created_at timestamptz default now());
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role app_role not null default 'BILLING_STAFF', branch_id uuid references branches(id), created_at timestamptz default now());
create table medicines (id uuid primary key default uuid_generate_v4(), name text not null, generic_name text, brand text, category text, manufacturer text, hsn_code text, gst_rate numeric(5,2) default 0, barcode text unique, prescription_required boolean default false, status text default 'ACTIVE', created_at timestamptz default now());
create table batches (id uuid primary key default uuid_generate_v4(), medicine_id uuid not null references medicines(id), branch_id uuid not null references branches(id), batch_number text not null, manufacturing_date date, expiry_date date not null, purchase_price numeric(12,2) not null, mrp numeric(12,2) not null, selling_price numeric(12,2) not null, received_quantity integer not null default 0, available_quantity integer not null default 0, status text default 'AVAILABLE', unique(medicine_id, branch_id, batch_number));
create table stock_movements (id uuid primary key default uuid_generate_v4(), batch_id uuid not null references batches(id), branch_id uuid not null references branches(id), type stock_movement_type not null, quantity integer not null, reference_id uuid, note text, created_by uuid references profiles(id), created_at timestamptz default now());
create table sales (id uuid primary key default uuid_generate_v4(), branch_id uuid not null references branches(id), invoice_number text unique not null, customer_name text, customer_mobile text, subtotal numeric(12,2) not null, discount numeric(12,2) default 0, tax numeric(12,2) default 0, total numeric(12,2) not null, payment_method text not null, payment_reference text, status text default 'COMPLETED', created_by uuid references profiles(id), created_at timestamptz default now());
create table sale_items (id uuid primary key default uuid_generate_v4(), sale_id uuid not null references sales(id) on delete cascade, medicine_id uuid not null references medicines(id), batch_id uuid not null references batches(id), quantity integer not null, unit_price numeric(12,2) not null, gst_rate numeric(5,2) default 0);
create index batches_expiry_idx on batches(branch_id, expiry_date); create index stock_movement_branch_idx on stock_movements(branch_id, created_at);
alter table branches enable row level security; alter table profiles enable row level security; alter table medicines enable row level security; alter table batches enable row level security; alter table stock_movements enable row level security; alter table sales enable row level security; alter table sale_items enable row level security;
create or replace function my_branch() returns uuid language sql stable as $$ select branch_id from profiles where id=auth.uid() $$;
create policy "branch staff read branches" on branches for select using (id=my_branch() or exists(select 1 from profiles where id=auth.uid() and role='OWNER'));
create policy "staff read medicines" on medicines for select using (auth.uid() is not null);
create policy "branch stock access" on batches for select using (branch_id=my_branch() or exists(select 1 from profiles where id=auth.uid() and role='OWNER'));
create policy "branch sales access" on sales for select using (branch_id=my_branch() or exists(select 1 from profiles where id=auth.uid() and role='OWNER'));
